using System;using System.Collections.Generic;/// <summary>/// Represents a node in the Jump List./// </summary>class JumpListNode<T> where T : IComparable<T>{public T Value;public JumpListNode<T> Next;public JumpListNode<T> Jump;public JumpListNode(T value){Value = value;Next = null;Jump = null;}}/// <summary>/// Represents a Jump List data structure./// </summary>class JumpList<T> where T : IComparable<T>{private JumpListNode<T> head;private int size;private int jumpFactor;/// <summary>/// Initializes a new instance of the Jump List./// </summary>public JumpList(int jumpFactor = 4){this.jumpFactor = jumpFactor;head = null;size = 0;}/// <summary>/// Inserts a new element into the Jump List./// </summary>public void Insert(T value){var newNode = new JumpListNode<T>(value);if (head == null || head.Value.CompareTo(value) > 0){newNode.Next = head;head = newNode;}else{var current = head;while (current.Next != null && current.Next.Value.CompareTo(value) < 0){current = current.Next;}newNode.Next = current.Next;current.Next = newNode;}size++;UpdateJumps();}/// <summary>/// Searches for an element in the Jump List./// </summary>public bool Search(T value){var current = head;while (current != null){if (current.Value.CompareTo(value) == 0){return true;}if (current.Jump != null && current.Jump.Value.CompareTo(value) <= 0){current = current.Jump;}else{current = current.Next;}}return false;}/// <summary>/// Deletes an element from the Jump List./// </summary>public bool Delete(T value){if (head == null)return false;if (head.Value.CompareTo(value) == 0){head = head.Next;size--;UpdateJumps();return true;}var current = head;while (current.Next != null && current.Next.Value.CompareTo(value) < 0){current = current.Next;}if (current.Next != null && current.Next.Value.CompareTo(value) == 0){current.Next = current.Next.Next;size--;UpdateJumps();return true;}return false;}/// <summary>/// Updates the jump pointers in the Jump List./// </summary>private void UpdateJumps(){if (head == null)return;var current = head;var jumpNode = head;int count = 0;while (current != null){if (count % jumpFactor == 0){jumpNode = current;}current.Jump = jumpNode;current = current.Next;count++;}}/// <summary>/// Gets the size of the Jump List./// </summary>public int Size => size;}